import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class B {
    static PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        FS in = new FS();
        long R = in.nextLong();
        long C = in.nextLong();
        long result = computeMinimum(R, C);
        out.println(result);
        out.close();
    }

    static long computeMinimum(long r, long c) {
        if (r < 3 && c < 3) return 0;
        if (r == 1) {
            long total = c;
            long mod = c % 6;
            if (mod != 0) {
                if (mod <= 3) total -= mod;
                else if (mod == 4) total -= 2;
                else total -= 1;
            }
            return total;
        }
        if (r == 2) {
            if (c == 3 || c == 7) return r * (c - 1);
            return r * c;
        }
        long totalCells = r * c;
        if (totalCells % 2 == 0) return totalCells;
        return totalCells - 1;
    }

    static class FS {
        BufferedReader br;
        StringTokenizer st;
        public FS() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try { st = new StringTokenizer(br.readLine()); }
                catch (Exception e) { throw new RuntimeException(e); }
            }
            return st.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
        double nextDouble() { return Double.parseDouble(next()); }
        long nextLong() { return Long.parseLong(next()); }
        int[] readIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) arr[i] = nextInt();
            return arr;
        }
        long[] readLongArray(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) arr[i] = nextLong();
            return arr;
        }
        char[][] readGrid(int r, int c) {
            char[][] grid = new char[r][c];
            for (int i = 0; i < r; i++) {
                char[] line = next().toCharArray();
                for (int j = 0; j < c; j++) {
                    grid[i][j] = line[j];
                }
            }
            return grid;
        }
    }
}
